const root=document.querySelector('#screen');
const nav=document.querySelectorAll('[data-screen]');
const screenHead=(n,title,sub)=>`<div class="screen-title"><div><div class="kicker">ЭКРАН ${n}</div><h1>${title}</h1><p>${sub}</p></div><div class="screen-actions"><button class="btn">ОТКРЫТЬ ЖУРНАЛ</button><button class="btn blue">ПРОВЕРИТЬ ОБОРУДОВАНИЕ</button></div></div>`;
const stage=(name,value,cls='')=>`<div class="stage ${cls}"><i>${cls==='done'?'✓':cls==='current'?'●':'○'}</i><span>${name}</span><b>${value}</b></div>`;
const tableRows=`<tr><td>Адаптер УБСИ</td><td>ROKT · 204 bytes</td><td class="ok">ГОТОВ</td></tr><tr><td>ИСД</td><td>type=5 · bus=1</td><td class="ok">ГОТОВ</td></tr><tr><td>В7-78/1</td><td>reference voltage</td><td class="ok">ГОТОВ</td></tr><tr><td>Р4831</td><td>manual input</td><td class="warn">ПОДТВЕРДИТЬ</td></tr>`;
function selectScreen(){return screenHead('00','Выбор проверки','УБСИ · проверка ЯЛК-96 и ЯТП · ТУ 5.6')+`<div class="selector-row"><div class="selector active" data-screen="yalk"><div class="symbol">∿</div><div><h2>ЯЛК-96</h2><p>Поток, адреса и каналы<br>80 каналов · калибровка</p></div></div><div class="selector" data-screen="ytp"><div class="symbol">Ω</div><div><h2>ЯТП</h2><p>Термосопротивления<br>30 каналов · 0 / 120 / 240 Ом</p></div></div><div class="selector" data-screen="combined"><div class="symbol">↗</div><div><h2>ЯЛК-96 + ЯТП</h2><p>Полная проверка<br>совмещённый прогон</p></div></div></div><div class="notice"><b>ПОДКЛЮЧЕНИЕ СТЕНДА:</b> ПК стенда · адаптер UDP 192.168.0.115 · ИСД 192.168.0.101 · В7-78/1 подключён</div><div class="cols"><div class="panel"><div class="panel-head"><h2>ПАРАМЕТРЫ ЗАПУСКА</h2><span class="tag ok">СТЕНД ГОТОВ</span></div><div class="form-grid"><div class="field"><label>ЗАВОДСКОЙ НОМЕР</label><input placeholder="Введите номер"></div><div class="field"><label>ТУ</label><input value="5.6" readonly></div></div><div class="divider"></div><p class="muted">Выбранный режим: <b>ЯЛК-96</b></p><button class="btn blue" data-screen="yalk">ЗАПУСТИТЬ ВЫБРАННЫЙ РЕЖИМ</button></div><div class="panel"><div class="panel-head"><h2>ОБОРУДОВАНИЕ</h2><span class="tag ok">6 / 6 ONLINE</span></div><table class="table">${tableRows}</table></div></div>`}
function yalkScreen(){return screenHead('01','Проверка ЯЛК-96','Поток, адреса и каналы · 80 адресов · source: адаптер + В7')+`<div class="notice"><b>ТЕКУЩАЯ ПРОЦЕДУРА:</b> ROKT init → 204-byte ЯЛК → ИСД 0 / 3,1 / 6,2 В → В7 → 16 fresh samples → calibration 97/99 → verdict</div><div class="cols-wide"><div><div class="panel"><div class="panel-head"><h2>ХОД ИЗМЕРЕНИЙ</h2><span class="tag ok">КАНАЛ 57 · ВЫПОЛНЯЕТСЯ</span></div><div class="plot"><span class="plot-label">АДРЕС 57 · V7 / ЯЛК · ВРЕМЯ, сек</span><svg viewBox="0 0 800 210" preserveAspectRatio="none"><polyline points="0,190 65,188 120,170 180,176 240,144 300,149 360,104 420,110 490,75 550,80 620,42 680,50 800,18" fill="none" stroke="#63a8ff" stroke-width="3"/><polyline points="0,194 65,192 120,174 180,180 240,148 300,153 360,108 420,114 490,79 550,84 620,46 680,54 800,22" fill="none" stroke="#5bd39a" stroke-width="2" stroke-dasharray="5 4"/></svg></div><div class="bottom-progress"><span>Выполнено <b>57 / 80</b></span><div class="progress"><i style="width:71%"></i></div><span>71 %</span></div></div><div class="panel" style="margin-top:10px"><div class="panel-head"><h2>РЕЗУЛЬТАТЫ КАНАЛОВ</h2><span class="kicker">16 FRESH SAMPLES</span></div><table class="table"><tr><th>АДРЕС</th><th>ТОЧКА</th><th>ЗАДАНО</th><th>В7, В</th><th>ЯЛК, В</th><th>γ, %</th><th>ИТОГ</th></tr><tr class="selected"><td>57</td><td>1</td><td>3,100</td><td>3,107</td><td>3,105</td><td class="ok">-0,032</td><td class="ok">ОК</td></tr><tr><td>56</td><td>1</td><td>3,100</td><td>3,104</td><td>3,102</td><td class="ok">+0,018</td><td class="ok">ОК</td></tr><tr><td>59</td><td>1</td><td>3,100</td><td>3,112</td><td>3,110</td><td class="warn">+0,212</td><td class="warn">ПРОВЕРКА</td></tr></table></div></div><div><div class="panel"><div class="panel-head"><h2>ЭТАПЫ</h2><span class="kicker">ЯЛК-96</span></div>${stage('Подготовка стенда','ОК','done')}${stage('Калибровка 97/99','ОК','done')}${stage('Каналы ЯЛК','57 / 80','current')}${stage('Каналы ЯТП','ожидание')}${stage('Завершение','ожидание')}<div class="current-box"><div class="kicker">ТЕКУЩЕЕ ИЗМЕРЕНИЕ</div><div class="big">АДРЕС 57</div><div class="reading"><span>Задано</span><b>3,100 В</b><span>В7</span><b>3,107 В</b><span>ЯЛК</span><b>3,105 В</b><span>γ</span><b class="ok">-0,032 %</b><span>Допуск</span><b>±0,5 %</b></div></div></div><div class="panel" style="margin-top:10px"><div class="panel-head"><h2>ПОТОК</h2><span class="tag ok">АКТИВЕН</span></div><p class="sub">ПАКЕТЫ　12 458</p><p class="sub">TIMEOUT　0</p><p class="sub">DROPPED　0</p><p class="sub">LAST SEQUENCE　45 221</p></div></div></div>`}
function ytpScreen(){return screenHead('02','Проверка ЯТП','30 каналов · магазин Р4831 · общий X123 · постоянные 120 Ом')+`<div class="notice"><b>ДЕЙСТВИЕ ОПЕРАТОРА:</b> установите сопротивление на магазине Р4831, введите фактическое значение и подтвердите точку.</div><div class="cols-wide"><div class="panel"><div class="panel-head"><h2>КАНАЛ / СОПРОТИВЛЕНИЕ</h2><span class="tag warn">ТРЕБУЕТСЯ ВВОД</span></div><div class="form-grid"><div class="field"><label>КАНАЛ</label><select><option>1</option><option>2</option><option>30</option></select></div><div class="field"><label>ФАКТИЧЕСКОЕ, ОМ</label><input value="120,00"></div></div><button class="btn blue">ПОДТВЕРДИТЬ 120 ОМ</button><div class="divider"></div><table class="table"><tr><th>КАНАЛ</th><th>RAW</th><th>СОПРОТИВЛЕНИЕ, Ω</th><th>ОТКЛОНЕНИЕ</th><th>СТАТУС</th></tr><tr class="selected"><td>1</td><td>0x8012</td><td>120,12</td><td>+0,05</td><td class="ok">ОК</td></tr><tr><td>2</td><td>0x7FF0</td><td>119,98</td><td>-0,01</td><td class="ok">ОК</td></tr><tr><td>3</td><td>0x7FEE</td><td>119,95</td><td>-0,02</td><td class="ok">ОК</td></tr></table></div><div><div class="panel"><div class="panel-head"><h2>ЭТАПЫ</h2><span class="kicker">ЯТП</span></div>${stage('Подготовка стенда','ОК','done')}${stage('Перевод адаптера','ОК','done')}${stage('Каналы 1–30','1 / 30','current')}${stage('Калибровка','ожидание')}${stage('Сброс','ожидание')}</div><div class="panel" style="margin-top:10px"><h2>КАДРЫ АДАПТЕРА</h2><p class="sub">Формат: 68 байт · Header: 01 00 34 00</p><p class="sub">0x8000 = отсутствие измерения</p></div></div></div>`}
function combinedScreen(){return screenHead('03','Совмещённая проверка ЯЛК-96 + ЯТП','Полная проверка · общий прогресс · отчёт после сброса')+`<div class="notice"><b>ПРЕДВАРИТЕЛЬНЫЙ VERDICT:</b> выполнение продолжается · обе линии должны завершить этапы без ошибок.</div><div class="cols-wide"><div><div class="panel"><div class="panel-head"><h2>ОБЩИЙ ПРОГРЕСС</h2><span class="tag ok">75 %</span></div>${stage('Инициализация','ОК','done')}${stage('Поток ЯЛК','ОК','done')}${stage('Поток ЯТП','ОК','done')}${stage('Сверка каналов','75 %','current')}${stage('Формирование отчёта','ожидание')}<div class="bottom-progress"><span>Общий прогресс</span><div class="progress"><i style="width:75%"></i></div><b>75 %</b></div></div><div class="grid g2" style="margin-top:10px"><div class="panel"><div class="panel-head"><h2>ЯЛК</h2><span class="tag ok">ОК</span></div><table class="table"><tr><th>АДРЕС</th><th>γ, %</th><th>ИТОГ</th></tr><tr><td>1</td><td>0,00</td><td class="ok">ОК</td></tr><tr><td>57</td><td>-0,03</td><td class="ok">ОК</td></tr></table></div><div class="panel"><div class="panel-head"><h2>ЯТП</h2><span class="tag ok">30 / 30</span></div><table class="table"><tr><th>КАНАЛ</th><th>R, Ω</th><th>ИТОГ</th></tr><tr><td>1</td><td>120,12</td><td class="ok">ОК</td></tr><tr><td>…</td><td>120,03</td><td class="ok">ОК</td></tr></table></div></div></div><div><div class="panel"><div class="panel-head"><h2>ПРЕДВАРИТЕЛЬНЫЙ ИТОГ</h2><span class="tag ok">PASS</span></div><div class="metric ok">PASS　✓</div><p class="sub">Можно формировать отчёт после завершения сброса.</p><button class="btn blue">СОХРАНИТЬ ОТЧЁТ</button></div><div class="panel" style="margin-top:10px"><h2>СОБЫТИЯ</h2><p class="sub">10:30:01　INIT_OK</p><p class="sub">10:30:12　ULK_STREAM_OK</p><p class="sub">10:30:17　YTP_STREAM_OK</p></div></div></div>`}
function reports(){return screenHead('R','Архив отчётов','HTML · CSV · подробная ведомость каналов · PDF после шаблона ОТК')+`<div class="panel"><div class="form-grid"><div class="field"><label>ПОИСК</label><input placeholder="ID запуска, номер, процедура"></div><div class="field"><label>ПЕРИОД</label><select><option>Последние 30 дней</option></select></div></div></div><div class="panel" style="margin-top:10px"><div class="panel-head"><h2>ЗАПУСКИ</h2><button class="btn blue">ЭКСПОРТ CSV</button></div><table class="table"><tr><th>ВРЕМЯ</th><th>ПРОЦЕДУРА</th><th>ОБЪЕКТ</th><th>ИТОГ</th><th>ФАЙЛЫ</th></tr><tr><td>05.09.2026 14:25</td><td>ЯЛК-96 + ЯТП</td><td>KTMA-01-2026-009</td><td class="ok">ОК</td><td>HTML · CSV</td></tr><tr><td>05.09.2026 13:58</td><td>ЯТП · 120 Ом</td><td>KTMA-01-2026-009</td><td class="bad">НЕ ОК</td><td>HTML · CSV</td></tr></table></div>`}function plugins(){return screenHead('P','Плагины КТМА','КТМА — совокупность плагинов стендового ПО · инженерский режим')+`<div class="plugin-grid"><div class="panel"><div class="panel-head"><h2>КАРТА ПОДКЛЮЧЕНИЙ</h2><span class="tag ok">6 / 6</span></div><table class="table"><tr><th>ПЛАГИН</th><th>CAPABILITY</th><th>СТАТУС</th></tr><tr><td>Адаптер УБСИ</td><td>ulk.parameter_source</td><td class="ok">ГОТОВ</td></tr><tr><td>ИСД</td><td>stand.switch_matrix</td><td class="ok">ГОТОВ</td></tr><tr><td>В7-78/1</td><td>measure.reference_voltage</td><td class="ok">ГОТОВ</td></tr><tr><td>«Орбита»</td><td>orbita.parameter_source</td><td class="ok">ГОТОВ</td></tr></table></div><div class="panel"><div class="panel-head"><h2>ДИАГНОСТИКА АДАПТЕРА</h2><span class="tag ok">REAL</span></div><p class="sub">ROKT / ЯЛК-204 / ЯТП-68</p><p>192.168.0.115:1113 · broadcast receive</p><div class="divider"></div><p class="sub">Последняя операция</p><p>read_frame · sequence 45 221</p><button class="btn blue">БЕЗОПАСНАЯ ПРОБА</button></div></div>`}const pages={select:selectScreen,yalk:yalkScreen,ytp:ytpScreen,combined:combinedScreen,reports,plugins};function render(k){root.innerHTML=`<div class="screen">${pages[k]()}</div>`;nav.forEach(b=>b.classList.toggle('active',b.dataset.screen===k));document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>render(b.dataset.screen))}nav.forEach(b=>b.onclick=()=>render(b.dataset.screen));render('select');
function scenarioEditor(){return screenHead('04','Редактор сценария','Инженерский контур · черновик · валидация перед публикацией')+`<div class="notice"><b>ВНИМАНИЕ:</b> опубликованный сценарий заблокирован. Изменения сохраняются только в черновик.</div><div class="cols-wide"><div class="panel"><div class="panel-head"><h2>СХЕМА ШАГОВ</h2><span class="tag warn">v1.4-draft</span></div>${stage('Инициализация стенда','ОК','done')}${stage('Поток ЯЛК · 204 bytes','ОК','done')}${stage('Точки 0 / 3,1 / 6,2 В','изменён','current')}${stage('Калибровка 97 / 99','ожидание')}${stage('Вердикт и сброс','ожидание')}<div class="divider"></div><button class="btn blue">ДОБАВИТЬ ШАГ</button> <button class="btn">ПРОВЕРИТЬ ПРИВЯЗКИ</button></div><div class="panel"><div class="panel-head"><h2>YAML · ТЕКУЩИЙ ШАГ</h2><span class="tag ok">СИНТАКСИС ОК</span></div><pre class="code">id: yalk_voltage_points · name: ЯЛК-96 · points: [0.00, 3.10, 6.20] · bus: 1 · calibration: [97, 99] · acceptance: gamma &lt;= 0.5</pre><button class="btn">ПОКАЗАТЬ DIFF</button> <button class="btn blue">СОХРАНИТЬ ЧЕРНОВИК</button></div></div>`}
function reportEditor(){return screenHead('05','Редактор отчёта','Метаданные и оформление · измерения доступны только для чтения')+`<div class="notice"><b>ИСТОЧНИК:</b> KTMA-01-2026-009 · ЯЛК-96 + ЯТП · сценарий v1.3 · профиль KTMA-01</div><div class="cols"><div class="panel"><div class="panel-head"><h2>МЕТАДАННЫЕ ПРОТОКОЛА</h2><span class="tag ok">ИЗМЕРЕНИЯ LOCKED</span></div><div class="form-grid"><div class="field"><label>ЗАВОДСКОЙ НОМЕР</label><input value="KTMA-01-2026-009"></div><div class="field"><label>ТУ / МЕТОДИКА</label><input value="ТУ 5.6"></div><div class="field"><label>ОПЕРАТОР</label><input value="Иванов И.И."></div><div class="field"><label>ДАТА ЗАПУСКА</label><input value="05.09.2026 14:25"></div></div><div class="field"><label>КОММЕНТАРИЙ</label><textarea>Проверка выполнена на стенде KTMA-01. Все обязательные каналы обработаны.</textarea></div><button class="btn blue">СОХРАНИТЬ МЕТАДАННЫЕ</button></div><div class="panel"><div class="panel-head"><h2>ПРЕДПРОСМОТР</h2><span class="kicker">HTML · CSV · PDF PLACEHOLDER</span></div><div class="report-preview"><div class="report-title">ПРОТОКОЛ ПРОВЕРКИ УБСИ</div><div class="report-rule"></div><p>Объект: <b>KTMA-01-2026-009</b></p><p>Методика: ТУ 5.6 · ЯЛК-96 + ЯТП</p><p>Итог: <span class="ok">ОК</span></p></div><button class="btn">ОТКРЫТЬ HTML</button> <button class="btn blue">СОХРАНИТЬ ОТЧЁТ</button></div></div>`}
function forms(){return screenHead('F','Формы и подтверждения','Операторские и инженерские формы · обязательные поля отмечены ◆')+`<div class="form-grid"><div class="panel"><div class="panel-head"><h2>ВЫБОР ОБЪЕКТА И ПРОЦЕДУРЫ</h2><span class="tag ok">ОПЕРАТОР</span></div><div class="field"><label>ЗАВОДСКОЙ НОМЕР ◆</label><input placeholder="Введите номер изделия"></div><div class="field"><label>ПРОЦЕДУРА ◆</label><select><option>ЯЛК-96 · 80 каналов</option><option>ЯТП · 30 каналов</option><option>ЯЛК-96 + ЯТП</option></select></div><div class="field"><label>ПРОФИЛЬ СТЕНДА</label><select><option>KTMA-01 · основной</option></select></div><button class="btn blue">ПОДТВЕРДИТЬ ВЫБОР</button></div><div class="panel"><div class="panel-head"><h2>РУЧНОЙ ВВОД Р4831</h2><span class="tag warn">ЯТП</span></div><p class="sub">Магазин подключён к общему X123. Оператор задаёт сопротивление физически.</p><div class="form-grid"><div class="field"><label>КАНАЛ ◆</label><select><option>1</option><option>2</option><option>30</option></select></div><div class="field"><label>ФАКТИЧЕСКОЕ, ОМ ◆</label><input value="120,00"></div></div><button class="btn blue">ПОДТВЕРДИТЬ ТОЧКУ</button></div><div class="panel"><div class="panel-head"><h2>ПОДТВЕРЖДЕНИЕ ЗАПУСКА</h2><span class="tag bad">ТРЕБУЕТСЯ</span></div><label class="check"><input type="checkbox"> Р4831 установлен на 120 Ом</label><label class="check"><input type="checkbox"> Защитный кожух закрыт</label><label class="check"><input type="checkbox"> Объект и методика сверены</label><div class="divider"></div><button class="btn blue">ПОДТВЕРДИТЬ УСЛОВИЯ</button></div><div class="panel"><div class="panel-head"><h2>ФИЛЬТР ОТЧЁТОВ</h2><span class="tag ok">ПОИСК</span></div><div class="form-grid"><div class="field"><label>ПЕРИОД</label><select><option>Последние 30 дней</option></select></div><div class="field"><label>ИТОГ</label><select><option>Все состояния</option><option>ОК</option><option>НЕ ОК</option></select></div></div><button class="btn">ПРИМЕНИТЬ ФИЛЬТР</button></div></div>`}
pages.scenario=scenarioEditor;pages['report-editor']=reportEditor;pages.forms=forms;nav.forEach(b=>b.onclick=()=>render(b.dataset.screen));render('select');
